describe('handle', () => {
  let baseConfig: ConnectorConfig;
  let basePayload: GitHubIssuePayload;

  beforeEach(() => {
    baseConfig = {
      linearApiKey: 'test-linear-key',
      linearTriageTeamId: 'TRIAGE_TEAM_UUID',
    };
    basePayload = {
      action: 'labeled',
      issue: {
        title: 'Test issue',
        body: 'Test description',
        labels: [{ name: 'bug' }, { name: 'enhancement' }],
        user: { login: 'testuser' },
        html_url: 'https://github.com/owner/repo/issues/1',
      },
      repository: { full_name: 'owner/repo' },
      sender: { login: 'testuser' },
    };
  });

  it('creates a Linear issue on happy path with correct request body', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.linear.app/graphql' && req.method === 'POST'
        ? jsonResponse(TARGET_ENDPOINTS[0].response)
        : jsonResponse({ error: 'not found' }, 404),
    );
    const config = { ...baseConfig, fetch };
    const result = await handle(basePayload, config);

    expect(calls).toHaveLength(1);
    const call = calls[0];
    expect(call.method).toBe('POST');
    expect(call.url).toBe('https://api.linear.app/graphql');
    expect(call.headers.get('authorization')).toBe('Bearer test-linear-key');
    expect(call.headers.get('content-type')).toBe('application/json');

    const bodyJson = call.json as { query: string; variables: { input: { title: string; description: string; teamId: string } } };
    expect(bodyJson.variables.input.title).toBe('Test issue');
    expect(bodyJson.variables.input.description).toContain('Test description');
    expect(bodyJson.variables.input.description).toContain('https://github.com/owner/repo/issues/1');
    expect(bodyJson.variables.input.description).toContain('@testuser');
    expect(bodyJson.variables.input.teamId).toBe('TRIAGE_TEAM_UUID');

    expect(result.linearIssueId).toBe('LINEAR-123');
    expect(result.linearIssueTitle).toBe('Fix login button alignment');
  });

  it('uses Bearer authentication from config', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.linear.app/graphql' ? jsonResponse(TARGET_ENDPOINTS[0].response) : jsonResponse({}, 404),
    );
    const config = { ...baseConfig, linearApiKey: 'different-key', fetch };
    await handle(basePayload, config);
    expect(calls[0].headers.get('authorization')).toBe('Bearer different-key');
  });

  it('maps fields correctly: title, description with reference, author, teamId', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.linear.app/graphql' ? jsonResponse(TARGET_ENDPOINTS[0].response) : jsonResponse({}, 404),
    );
    const payload: GitHubIssuePayload = {
      ...basePayload,
      issue: {
        ...basePayload.issue,
        title: 'Custom title',
        body: 'Custom body',
        user: { login: 'customauthor' },
        html_url: 'https://github.com/custom/repo/issues/99',
      },
    };
    await handle(payload, { ...baseConfig, fetch });
    const bodyJson = calls[0].json as { variables: { input: { title: string; description: string; teamId: string } } };
    expect(bodyJson.variables.input.title).toBe('Custom title');
    expect(bodyJson.variables.input.description).toContain('Custom body');
    expect(bodyJson.variables.input.description).toContain('https://github.com/custom/repo/issues/99');
    expect(bodyJson.variables.input.description).toContain('@customauthor');
    expect(bodyJson.variables.input.teamId).toBe('TRIAGE_TEAM_UUID');
  });

  it('throws on missing required field: action', async () => {
    const payload = { ...basePayload, action: undefined as unknown as string };
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow(
      'Missing required field: action',
    );
  });

  it('throws on missing required field: issue.title', async () => {
    const payload = { ...basePayload, issue: { ...basePayload.issue, title: '' } };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.title');
  });

  it('throws on missing required field: issue.body', async () => {
    const payload = { ...basePayload, issue: { ...basePayload.issue, body: null } };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.body');
  });

  it('throws on missing required field: issue.labels', async () => {
    const payload = { ...basePayload, issue: { ...basePayload.issue, labels: undefined as unknown as GitHubIssuePayload['issue']['labels'] } };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.labels');
  });

  it('throws on missing required field: issue.user.login', async () => {
    const payload = { ...basePayload, issue: { ...basePayload.issue, user: { login: '' } } };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.user.login');
  });

  it('throws on missing required field: issue.html_url', async () => {
    const payload = { ...basePayload, issue: { ...basePayload.issue, html_url: '' } };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.html_url');
  });

  it('throws when action is not labeled or opened', async () => {
    const payload = { ...basePayload, action: 'closed' };
    await expect(handle(payload, baseConfig)).rejects.toThrow("Unsupported action: closed. Expected 'labeled' or 'opened'.");
  });

  it('throws when bug label is not present', async () => {
    const payload = { ...basePayload, issue: { ...basePayload.issue, labels: [{ name: 'enhancement' }] } };
    await expect(handle(payload, baseConfig)).rejects.toThrow("Label 'bug' not found in issue labels.");
  });

  it('throws on non-2xx response from Linear API', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.linear.app/graphql' ? jsonResponse({ error: 'Unauthorized' }, 401) : jsonResponse({}, 404),
    );
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear API error: 401 Unauthorized at POST https://api.linear.app/graphql',
    );
    expect(calls).toHaveLength(1);
  });

  it('throws on GraphQL errors in response', async () => {
    const { fetch } = fakeFetch((req) =>
      req.url === 'https://api.linear.app/graphql'
        ? jsonResponse({ errors: [{ message: 'Team not found' }] })
        : jsonResponse({}, 404),
    );
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow('Linear GraphQL errors: Team not found');
  });

  it('throws when issueCreate returns success false', async () => {
    const { fetch } = fakeFetch((req) =>
      req.url === 'https://api.linear.app/graphql'
        ? jsonResponse({ data: { issueCreate: { success: false, issue: null } } })
        : jsonResponse({}, 404),
    );
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear issueCreate returned unexpected response',
    );
  });
});

